window.bookSummaryJSON = "<p>From the bestselling author Ben Alderson comes a twisted and spicy reimagining of the Little Red Riding Hood tale. Alpha of Mortal Flesh is a standalone in the Darkmourn Universe and follows Rhory as he uncovers a new race of paranormal creatures that threaten everything dear to him.</p> <p>Rise of the wolves.</p> <p>Beware.</p> <p>Contains mature themes.</p>"; 
